import time


def wait_for_io():
    time.sleep(0.5)            # stands in for a network call or a slow disk


def crunch_numbers():
    total = 0
    for i in range(5_000_000):
        total += i * i
    return total


for job in (wait_for_io, crunch_numbers):
    wall, cpu = time.perf_counter(), time.process_time()
    job()
    wall, cpu = time.perf_counter() - wall, time.process_time() - cpu
    print(f"{job.__name__:15} elapsed {wall:.2f}s  cpu {cpu:.2f}s")

