"""Run an I/O-bound job and a CPU-bound job three ways: one after another, in threads and in processes."""
import sys
import time
from concurrent.futures import ProcessPoolExecutor, ThreadPoolExecutor


def fake_download(n):
    """I/O-bound: waits, like a network call, then returns a small result."""
    time.sleep(0.25)
    return n * n


def count_primes(bounds):
    """CPU-bound: counts the primes in [start, stop) by trial division."""
    start, stop = bounds
    count = 0
    for n in range(max(start, 2), stop):
        if all(n % d for d in range(2, int(n ** 0.5) + 1)):
            count += 1
    return count


IO_JOBS = list(range(8))
CPU_JOBS = [(i * 50_000, (i + 1) * 50_000) for i in range(4)]


def run_sequential(fn, jobs):
    return [fn(job) for job in jobs]


def run_threads(fn, jobs, workers=4):
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return list(pool.map(fn, jobs))


def run_processes(fn, jobs, workers=4):
    # TODO: run fn over jobs in a ProcessPoolExecutor with `workers` processes
    #       and return the results as a list, in the same order as jobs.
    raise NotImplementedError


def main():
    gil = sys._is_gil_enabled() if hasattr(sys, "_is_gil_enabled") else True
    print(f"Python {sys.version.split()[0]}, GIL enabled: {gil}")
    for kind, fn, jobs, summary in (
        ("io", fake_download, IO_JOBS, lambda r: f"squares={sum(r)}"),
        ("cpu", count_primes, CPU_JOBS, lambda r: f"primes={sum(r)}"),
    ):
        for label, runner in (("sequential", run_sequential), ("threads", run_threads),
                              ("processes", run_processes)):
            start = time.perf_counter()
            results = runner(fn, jobs)
            elapsed = time.perf_counter() - start
            print(f"{kind:4} {label:11} {summary(results):14} {elapsed:6.2f}s")


if __name__ == "__main__":
    main()

