import time
from concurrent.futures import ThreadPoolExecutor, as_completed


def lookup(name, seconds):
    time.sleep(seconds)          # a blocking call, such as a database query
    if name == "broken":
        raise ConnectionError("lookup failed")
    return f"{name}: found"


jobs = {"slow": 0.3, "fast": 0.1, "broken": 0.2}
with ThreadPoolExecutor(max_workers=3) as pool:
    futures = {pool.submit(lookup, name, s): name for name, s in jobs.items()}
    for future in as_completed(futures):
        name = futures[future]
        try:
            print(future.result())
        except ConnectionError as exc:
            print(f"{name}: error: {exc}")

