"""Fetch twelve reports from a slow, blocking service. Make it concurrent with a thread pool."""
import time
from concurrent.futures import ThreadPoolExecutor, as_completed


def fetch_report(report_id):
    """Stands in for a blocking client library call (a database driver, a cloud SDK)."""
    time.sleep(0.2)
    if report_id == 7:
        raise ValueError(f"report {report_id} is corrupt")
    return {"id": report_id, "size": report_id * 100}


def fetch_all_sequentially(ids):
    reports, errors = [], []
    for report_id in ids:
        try:
            reports.append(fetch_report(report_id))
        except ValueError as exc:
            errors.append(str(exc))
    return reports, errors


def fetch_all_concurrently(ids, workers=4):
    # TODO: submit fetch_report(report_id) for every id to a ThreadPoolExecutor with
    #       `workers` threads, collect the results with as_completed, and put each
    #       error's message in errors. Return (reports sorted by id, errors).
    raise NotImplementedError


def main():
    ids = range(1, 13)
    for name, fn in (("sequential", fetch_all_sequentially), ("threads", fetch_all_concurrently)):
        start = time.perf_counter()
        reports, errors = fn(ids)
        elapsed = time.perf_counter() - start
        total = sum(r["size"] for r in reports)
        print(f"{name:10} fetched {len(reports)} reports, total size {total}, errors {errors}  ({elapsed:.2f}s)")


if __name__ == "__main__":
    main()

