def square(n):
    return n * n


def check(n):
    if n == 3:
        raise ValueError(f"bad item {n}")
    return n


if __name__ == "__main__":
    with ProcessPoolExecutor(max_workers=4) as pool:
        print(sum(pool.map(square, range(100_000), chunksize=1_000)))
        future = pool.submit(check, 3)
        try:
            future.result()
        except ValueError as exc:
            print(f"raised in a worker, re-raised here: {exc!r}")

