import asyncio

import jobs


def run(job):
    return asyncio.run(jobs.run_job(job, asyncio.Semaphore(1), jobs.Tracker()))


def test_a_quick_job_succeeds():
    assert run(("quick", 0.01, None)) == ("quick", "ok")


def test_a_slow_job_times_out(monkeypatch):
    monkeypatch.setattr(jobs, "TIMEOUT", 0.05)
    assert run(("slow", 1.0, None)) == ("slow", "timed out")


def test_an_error_is_reported():
    assert run(("bad", 0.01, KeyError("x"))) == ("bad", "failed: KeyError('x')")

"""A deliberately slow, unreliable local API for practising async clients. Standard library only.

    python slow_server.py         # serves http://127.0.0.1:8765 until you press Ctrl+C

GET /items/<id> answers {"id": <id>, "price": <id * 1.25>} after a short delay, except:
  ids divisible by 7   every other request for them fails with 503 Service Unavailable
                       (the first, the third...), so one retry succeeds
  id 13                takes 3 seconds, longer than a sensible client timeout
  ids above 100        404 Not Found
"""
import json
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

HOST, PORT, DELAY = "127.0.0.1", 8765, 0.1
hits = {}                         # requests so far for each id
hits_lock = threading.Lock()      # the server handles each request in its own thread


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        parts = self.path.strip("/").split("/")
        if len(parts) != 2 or parts[0] != "items" or not parts[1].isdigit():
            return self.reply(404, {"error": "not found"})
        item_id = int(parts[1])
        time.sleep(3 if item_id == 13 else DELAY)
        if item_id > 100:
            return self.reply(404, {"error": f"no item {item_id}"})
        if item_id % 7 == 0:
            with hits_lock:
                hits[item_id] = hits.get(item_id, 0) + 1
                busy = hits[item_id] % 2 == 1
            if busy:
                return self.reply(503, {"error": "busy, try again"})
        self.reply(200, {"id": item_id, "price": round(item_id * 1.25, 2)})

    def reply(self, status, body):
        data = json.dumps(body).encode()
        try:
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError):
            pass                  # the client gave up waiting (a timeout): nothing to send

    def log_message(self, fmt, *args):
        pass                      # keep the terminal quiet


if __name__ == "__main__":
    server = ThreadingHTTPServer((HOST, PORT), Handler)
    print(f"serving on http://{HOST}:{PORT} (Ctrl+C to stop)")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()

import asyncio

import httpx

import fetch_prices


def run(handler, ids):
    """Run fetch_all against a fake server: handler(request) returns the response."""
    async def go():
        transport = httpx.MockTransport(handler)
        async with httpx.AsyncClient(base_url="http://test", transport=transport) as client:
            return await fetch_prices.fetch_all(ids, client)
    return asyncio.run(go())


def test_a_503_is_retried_then_succeeds():
    calls = []

    def handler(request):
        calls.append(request.url.path)
        if len(calls) == 1:
            return httpx.Response(503)
        return httpx.Response(200, json={"id": 1, "price": 2.5})

    results, stats = run(handler, [1])
    assert results == {1: 2.5}
    assert calls == ["/items/1", "/items/1"]
    assert stats.retries == 1


def test_a_missing_item_gives_none():
    results, stats = run(lambda request: httpx.Response(404), [5])
    assert results == {5: None}
    assert stats.retries == 0


def test_timeouts_are_reported_after_every_attempt():
    def handler(request):
        raise httpx.ReadTimeout("too slow", request=request)

    results, stats = run(handler, [13])
    assert results == {13: "timed out"}
    assert stats.retries == fetch_prices.ATTEMPTS - 1


def test_no_more_than_max_in_flight_requests():
    async def handler(request):
        await asyncio.sleep(0.01)        # an async handler: requests overlap
        return httpx.Response(200, json={"price": 1.0})

    results, stats = run(handler, range(20))
    assert len(results) == 20
    assert stats.peak == fetch_prices.MAX_IN_FLIGHT

"""A local supplier API for the capstone: slow, paged and sometimes unreliable. Standard library only.

    python supplier_server.py        # serves http://127.0.0.1:8766 until you press Ctrl+C

GET /products?page=N   one page of product ids: {"page": N, "products": [...], "next_page": N + 1 or null}
                       (10 pages of 20 products, ids 1 to 200)
GET /products/<id>     {"id": ..., "name": ..., "prices": [30 recent prices]}, except:
    ids divisible by 17   every other request fails with 503 Service Unavailable, so one retry succeeds
    ids divisible by 41   always 500 Internal Server Error (retrying won't help)
    ids divisible by 50   take 4 seconds to answer
    ids above 200         404 Not Found
"""
import json
import random
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

HOST, PORT = "127.0.0.1", 8766
PAGES, PER_PAGE = 10, 20
hits = {}
hits_lock = threading.Lock()


def prices_for(product_id):
    rng = random.Random(product_id)
    base = 10 + product_id % 90
    return [round(base * (1 + rng.gauss(0, 0.04)), 2) for _ in range(30)]


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        url = urlparse(self.path)
        parts = url.path.strip("/").split("/")
        if parts == ["products"]:
            time.sleep(0.05)
            page = int(parse_qs(url.query).get("page", ["1"])[0])
            if not 1 <= page <= PAGES:
                return self.reply(404, {"error": f"no page {page}"})
            first = (page - 1) * PER_PAGE + 1
            return self.reply(200, {"page": page, "products": list(range(first, first + PER_PAGE)),
                                    "next_page": page + 1 if page < PAGES else None})
        if len(parts) == 2 and parts[0] == "products" and parts[1].isdigit():
            product_id = int(parts[1])
            time.sleep(4 if product_id % 50 == 0 else 0.1)
            if product_id > PAGES * PER_PAGE:
                return self.reply(404, {"error": f"no product {product_id}"})
            if product_id % 41 == 0:
                return self.reply(500, {"error": "internal error"})
            if product_id % 17 == 0:
                with hits_lock:
                    hits[product_id] = hits.get(product_id, 0) + 1
                    busy = hits[product_id] % 2 == 1
                if busy:
                    return self.reply(503, {"error": "busy, try again"})
            return self.reply(200, {"id": product_id, "name": f"Product {product_id}",
                                    "prices": prices_for(product_id)})
        self.reply(404, {"error": "not found"})

    def reply(self, status, body):
        data = json.dumps(body).encode()
        try:
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def log_message(self, fmt, *args):
        pass


if __name__ == "__main__":
    server = ThreadingHTTPServer((HOST, PORT), Handler)
    print(f"serving on http://{HOST}:{PORT} (Ctrl+C to stop)")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()

"""The capstone's CPU-heavy step. Pure Python, so it holds the GIL while it runs."""
import random


def risk_score(prices, rounds=10_000, seed=0):
    """The share of bootstrap resamples whose mean is more than 2% away from the overall mean.

    Deterministic for the same prices, rounds and seed; takes a noticeable fraction of a second."""
    rng = random.Random(seed)
    n = len(prices)
    mean = sum(prices) / n
    far = 0
    for _ in range(rounds):
        total = 0.0
        for _ in range(n):
            total += prices[rng.randrange(n)]
        if abs(total / n - mean) > 0.02 * mean:
            far += 1
    return round(far / rounds, 4)
